/*setSysopOrderChangeAfterQtyChange1*/

            UPDATE ICOMPORS
               SET STATUS        = DECODE(#{value},0,'D','R') ,
       CD_QTY     = #{value},
       CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                   CHANGE_TIME   = TO_CHAR(SYSDATE, 'HH24MISS')
             WHERE BUYER   = #{value}
               AND PO_NO   = #{value}
               AND PO_SEQ  = #{value}
               AND DS_DATE = #{value}

/*setSysopOrderChangeAfterQtyChange2*/

            UPDATE ICOMPRDT
               SET STATUS        =  DECODE(#{value},0,'D','R') ,
       PO_QTY = #{value},
       RECV_QTY = #{value},
       TARGET_QTY = DECODE(DOC_TYPE,'X',#{value},TARGET_QTY),
       CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                   CHANGE_TIME   = TO_CHAR(SYSDATE, 'HH24MISS')
             WHERE BUYER   = #{value}
               AND PR_NO   = #{value}
               AND PR_SEQ  = #{value}

/*setSysopOrderChangeAfterQtyChange3*/

            UPDATE ICOMIVDT                                                 
               SET STATUS        = DECODE(#{value},0,'D','R') ,
                   INV_QTY = #{value},
                   ITEM_AMT = TRUNC( #{value} * UNIT_PRICE,2),
                   CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                   CHANGE_TIME   = TO_CHAR(SYSDATE, 'HH24MISS')
             WHERE BUYER   = #{value}
               AND PO_NO   = #{value}
               AND PO_SEQ  = #{value}
               AND DS_DATE = #{value}
               AND STATUS != 'D'

/*setSysopOrderChangeAfterQtyChange5*/

             UPDATE ICOMPRHD 
                SET STATUS = DECODE((SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = #{value}  AND PR_NO = #{value}  AND STATUS IN ('C','R')),0,'D','R'),  
                    CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                    CHANGE_TIME   = TO_CHAR(SYSDATE,'HH24MISS')
              WHERE BUYER = #{value}
                AND PR_NO = #{value}
